            int idx = 0;
            for (int i = 0; i+1 < (int)num.size(); i++) {
                if (num[i] > num[i+1]) { idx = i; break; }
                if (i+1 == (int)num.size()-1) idx = num.size()-1;
            }
            num.erase(num.begin()+idx);
            k--;
        }
