class Solution {
public:
    int minRefuelStops(int target, int startFuel, vector<vector<int>>& stations) {
        priority_queue<int> pq;
        long long fuel = startFuel;
        int stops = 0, prev = 0;
        for (auto& s : stations) {
            fuel -= (s[0] - prev);
            prev = s[0];
            while (fuel < 0 && !pq.empty()) {
                fuel += pq.top(); pq.pop();
                stops++;
            }
            if (fuel < 0) return -1;
            pq.push(s[1]);
        }
        fuel -= (target - prev);
        while (fuel < 0 && !pq.empty()) {
            fuel += pq.top(); pq.pop();
            stops++;
        }
        return fuel >= 0 ? stops : -1;
    }
};

