int removeBoxes(vector<int>& boxes) {
    int n = boxes.size();
    function<int(int,int,int)> solve = [&](int l, int r, int k) -> int {
        if (l > r) return 0;
        while (l < r && boxes[r] == boxes[r-1]) { r--; k++; }
