int superEggDrop(int k, int n) {
    // dp[t][k] = max floors checkable with t moves and k eggs
    vector<vector<long long>> dp(n+1, vector<long long>(k+1, 0));
    int t = 0;
    while (dp[t][k] < n) {
        t++;
        for (int j = 1; j <= k; j++)
            dp[t][j] = dp[t-1][j-1] + dp[t-1][j] + 1;
    }
    return t;
}

