    vector<int> seq;
    for (int i = 0; i < 2*n; i++) seq.push_back(i);
    long long count = 0;
    do {
        bool valid = true;
        for (int i = 0; i < n && valid; i++) {
            int pi = -1, di = -1;
            for (int j = 0; j < 2*n; j++) {
                if (seq[j] == i) pi = j;
                if (seq[j] == i + n) di = j;
