#include <unordered_map>
using namespace std;

class Solution {
public:
    unordered_map<int, long long> priceMap;
    int M, N;

    long long solve(int h, int w) {
        int key = h * 201 + w;
        long long best = priceMap.count(key) ? priceMap[key] : 0;
        for (int cut = 1; cut < h; cut++)
            best = max(best, solve(cut, w) + solve(h - cut, w));
        for (int cut = 1; cut < w; cut++)
            best = max(best, solve(h, cut) + solve(h, w - cut));
        return best;
    }

    long long sellingWood(int m, int n, vector<vector<int>>& prices) {
        M = m; N = n;
        for (auto& p : prices) priceMap[p[0] * 201 + p[1]] = p[2];
        return solve(m, n);
    }
};

