class Solution {
public:
    unordered_map<string, int> memo;

    string collapse(string s) {
        bool changed = true;
        while (changed) {
            changed = false;
            int i = 0;
            while (i < (int)s.size()) {
                int j = i;
                while (j < (int)s.size() && s[j] == s[i]) j++;
                if (j - i >= 3) { s.erase(i, j - i); changed = true; }
                else i = j;
            }
        }
        return s;
    }

    int solve(string board, string hand) {
        if (board.empty()) return 0;
        string key = board + '#' + hand;
        if (memo.count(key)) return memo[key];
        int ans = INT_MAX;
        int i = 0;
        while (i < (int)board.size()) {
            int j = i;
            while (j < (int)board.size() && board[j] == board[i]) j++;
            char c = board[i];
            int need = 3 - (j - i);
            int cnt = count(hand.begin(), hand.end(), c);
            if (cnt >= need) {
                string newHand = hand;
                for (int k = 0; k < need; k++) newHand.erase(newHand.find(c), 1);
                string newBoard = collapse(board.substr(0, i) + board.substr(j));
                int sub = solve(newBoard, newHand);
                if (sub != -1) ans = min(ans, need + sub);
            }
            i = j;
        }
        return memo[key] = (ans == INT_MAX ? -1 : ans);
    }

    int findMinStep(string board, string hand) {
        sort(hand.begin(), hand.end());
        return solve(board, hand);
    }
};

