                int sz = intervals[i][1] - intervals[i][0] + 1;
                pq.push({sz, intervals[i][1]});
                i++;
            }
            while (!pq.empty() && pq.top().second < q) pq.pop();
            if (!pq.empty()) ans[qi] = pq.top().first;
        }
        return ans;
    }
