class Solution {
public:
    bool isPrintable(vector<vector<int>>& targetGrid) {
        int m = targetGrid.size(), n = targetGrid[0].size();
        unordered_map<int, array<int,4>> bounds;
        for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
            int c = targetGrid[i][j];
            if (!bounds.count(c)) bounds[c] = {i, j, i, j};
            else {
                bounds[c][0] = min(bounds[c][0], i);
                bounds[c][1] = min(bounds[c][1], j);
                bounds[c][2] = max(bounds[c][2], i);
                bounds[c][3] = max(bounds[c][3], j);
            }
        }
        // Build dependency graph
        unordered_map<int, unordered_set<int>> deps;
        for (auto& [c, b] : bounds) {
            for (int i = b[0]; i <= b[2]; i++) for (int j = b[1]; j <= b[3]; j++) {
                int other = targetGrid[i][j];
                if (other != c) deps[c].insert(other); // c depends on other (other printed after c)
            }
        }
        // Topological sort (Kahn's)
        unordered_map<int, int> indegree;
        for (auto& [c, _] : bounds) indegree[c] = 0;
        for (auto& [c, s] : deps) for (int d : s) indegree[d]++;
        vector<int> q;
        for (auto& [c, deg] : indegree) if (deg == 0) q.push_back(c);
        int processed = 0;
        while (!q.empty()) {
            int cur = q.back(); q.pop_back(); processed++;
            for (auto& [c, s] : deps) {
                if (s.count(cur)) {
                    s.erase(cur);
                    if (--indegree[c] == 0) q.push_back(c);
                }
            }
        }
        return processed == (int)bounds.size();
    }
};

