using namespace std;

class Solution {
private:
    int rows[9] = {}, cols[9] = {}, boxes[9] = {};
    bool canPlace(int row, int col, int num) {
        int bit = 1 << num;
        int box = (row / 3) * 3 + col / 3;
        return !(rows[row] & bit) && !(cols[col] & bit) && !(boxes[box] & bit);
    }
    void place(int row, int col, int num, bool set) {
        int bit = 1 << num;
        int box = (row / 3) * 3 + col / 3;
        if (set) { rows[row] |= bit; cols[col] |= bit; boxes[box] |= bit; }
        else { rows[row] &= ~bit; cols[col] &= ~bit; boxes[box] &= ~bit; }
    }
    bool solve(vector<vector<char>>& board, int pos) {
        while (pos < 81 && board[pos / 9][pos % 9] != '.') pos++;
        if (pos == 81) return true;
        int r = pos / 9, c = pos % 9;
        for (int num = 1; num <= 9; num++) {
            if (canPlace(r, c, num)) {
                board[r][c] = '0' + num;
                place(r, c, num, true);
                if (solve(board, pos + 1)) return true;
                board[r][c] = '.';
                place(r, c, num, false);
            }
        }
        return false;
    }
public:
    void solveSudoku(vector<vector<char>>& board) {
        for (int i = 0; i < 9; i++)
            for (int j = 0; j < 9; j++)
                if (board[i][j] != '.') {
                    int num = board[i][j] - '0';
                    place(i, j, num, true);
                }
        solve(board, 0);
    }
};

