            if (isValid(cur)) { result.push_back(cur); found = true; }
            if (found) continue;
            for (int i = 0; i < cur.size(); i++) {
                if (cur[i] != '(' && cur[i] != ')') continue;
                string next = cur.substr(0, i) + cur.substr(i + 1);
                if (!visited.count(next)) { visited.insert(next); q.push(next); }
            }
        }
        return result;
    }
};

