    vector<string> findRepeatedDnaSequences(string s) {
        if (s.size() <= 10) return {};
        unordered_map<char, int> encode = {{'A',0},{'C',1},{'G',2},{'T',3}};
        unordered_map<int, int> count;
        vector<string> result;
        int hash = 0;
        int mask = (1 << 20) - 1;
        for (int i = 0; i < 10; i++) hash = (hash << 2) | encode[s[i]];
        count[hash]++;
        for (int i = 10; i < (int)s.size(); i++) {
            hash = ((hash << 2) | encode[s[i]]) & mask;
            if (++count[hash] == 2) result.push_back(s.substr(i - 9, 10));
        }
        return result;
    }
};

