class Solution {
    int n;
    bool dfs(vector<int>& result, vector<bool>& visited) {
        if ((int)result.size() == (1 << n)) return true;
        int cur = result.back();
        for (int i = 0; i < n; i++) {
            int next = cur ^ (1 << i);
            if (!visited[next]) {
                visited[next] = true;
                result.push_back(next);
                if (dfs(result, visited)) return true;
                result.pop_back();
                visited[next] = false;
            }
        }
        return false;
    }
public:
    vector<int> grayCode(int n) {
        this->n = n;
        vector<bool> visited(1 << n, false);
        vector<int> result = {0};
        visited[0] = true;
        dfs(result, visited);
        return result;
    }
};

