public:
    int numberOfSteps(int num) {
        if (num == 0) return 0;
        int bits = 0, setBits = 0;
        int tmp = num;
        while (tmp) { bits++; setBits += tmp & 1; tmp >>= 1; }
        // Each bit except leading needs right-shift (1 step), each set bit needs extra subtract step
        return bits + setBits - 1;
    }
};

